// Difficulty distribution helpers
const difficultyDistribution = (index: number, total: number): "Easy" | "Medium" | "Hard" => {
  const ratio = index / total;
  if (ratio < 0.35) return "Easy";
  if (ratio < 0.75) return "Medium";
  return "Hard";
};

const generateAcceptance = (diff: string): string => {
  if (diff === "Easy") return `${Math.floor(Math.random() * 25 + 60)}%`;
  if (diff === "Medium") return `${Math.floor(Math.random() * 20 + 35)}%`;
  return `${Math.floor(Math.random() * 15 + 18)}%`;
};

// Seed the random number generator for consistent results
const seededRandom = (seed: number) => {
  const x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
};

// Generate all 4000 problems
function generateProblems(): CodingProblem[] {
  const allProblems: CodingProblem[] = [];
  let id = 1;

  // First pass: use all template problems (~480 problems from categories above)
  for (const cat of categories) {
    for (let i = 0; i < cat.problems.length; i++) {
      const p = cat.problems[i];
      const difficulty = difficultyDistribution(i, cat.problems.length);
      allProblems.push({
        id: id++,
        title: p.t,
        difficulty,
        category: cat.name,
        acceptance: generateAcceptance(difficulty),
        solved: false,
        description: p.d,
        hint: p.h,
      });
    }
  }

  // Second pass: generate variations to reach 4000
  const variations = [
    "II", "III", "IV", "V", "(Iterative)", "(Recursive)", "(Optimized)",
    "(Follow-up)", "(Hard Version)", "(Advanced)", "(In-Place)", "(Space Optimized)",
    "(With Constraints)", "(Variant)", "(Extended)",
  ];

  const extraDescModifiers = [
    "with additional space constraint of O(1)",
    "where the input can contain negative numbers",
    "in sorted order",
    "using constant extra space",
    "with at most k modifications allowed",
    "for a circular array",
    "where duplicates are allowed",
    "with weighted edges",
    "in reverse order",
    "with multiple queries",
    "using divide and conquer",
    "optimized for large inputs",
    "with streaming data",
    "in a matrix representation",
    "with backtracking pruning",
  ];

  let varIdx = 0;
  let modIdx = 0;

  while (allProblems.length < 4000) {
    for (const cat of categories) {
      for (const p of cat.problems) {
        if (allProblems.length >= 4000) break;

        const variation = variations[varIdx % variations.length];
        const mod = extraDescModifiers[modIdx % extraDescModifiers.length];
        const difficulty = difficultyDistribution(
          seededRandom(id) * cat.problems.length,
          cat.problems.length
        ) as "Easy" | "Medium" | "Hard";

        allProblems.push({
          id: id++,
          title: `${p.t} ${variation}`,
          difficulty,
          category: cat.name,
          acceptance: generateAcceptance(difficulty),
          solved: false,
          description: `${p.d} Solve this ${mod}.`,
          hint: p.h,
        });

        modIdx++;
        if (modIdx % extraDescModifiers.length === 0) varIdx++;
      }
      if (allProblems.length >= 4000) break;
    }
  }

  return allProblems.slice(0, 4000);
}

export const codingProblems = generateProblems();

export const problemCategories = [
  "All", ...categories.map(c => c.name)
];

export const defaultHints: Record<number, string> = {};
codingProblems.forEach(p => {
  defaultHints[p.id] = `💡 Hint: ${p.hint}`;
});

export const defaultDescriptions: Record<number, string> = {};
codingProblems.forEach(p => {
  defaultDescriptions[p.id] = p.description;
});
